    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)
    K = next(it)

    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> bool:
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    water_cycle = False
    roads = []

    for _ in range(M):
        a = next(it)
        b = next(it)
        t = next(it)
        if t == 1:
            if not union(a, b):
                water_cycle = True
        else:
            roads.append((a, b))

    if water_cycle:
        print("N")
        return

    for a, b in roads:
        union(a, b)

    roots = set()
    for i in range(1, N + 1):
        roots.add(find(i))
    c = len(roots)

    if M - (N - c) <= K:
        print("S")
    else:
        print("N")

